package com.ayush.stayscout.auth;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import java.nio.charset.StandardCharsets; import java.time.*; import java.util.*; import javax.crypto.SecretKey; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service;
@Service public class JwtService { private final SecretKey key; public JwtService(@Value("${app.jwt.secret}")String s){key=Keys.hmacShaKeyFor(s.getBytes(StandardCharsets.UTF_8));} public String token(User u){return Jwts.builder().subject(u.getId().toString()).claim("role",u.getRole().name()).issuedAt(new Date()).expiration(Date.from(Instant.now().plus(Duration.ofHours(1)))).signWith(key).compact();} public Claims claims(String t){return Jwts.parser().verifyWith(key).build().parseSignedClaims(t).getPayload();} }
